def road_kinds(spec: dict) -> list:
    """Sorted distinct kinds of road leaving any junction reachable from start."""
    adj = {}
    for s, t, k in spec["edges"]:
        adj.setdefault(s, []).append((t, k))
    seen = set()
    stack = [spec["start"]]
    kinds = set()
    while stack:
        n = stack.pop()
        if n in seen:
            continue
        seen.add(n)
        for t, k in adj.get(n, []):
            kinds.add(k)
            stack.append(t)
    return sorted(kinds)
```

