def engagement_report(spec: dict) -> str:
    """Rank users by total likes received on their posts: 'name=likes' comma-joined, likes desc then name."""
    users = sorted(set(spec["users"]))
    per_post = {}
    for l in spec["likes"]:
        if l[0] in users:
            per_post[l[1]] = per_post.get(l[1], 0) + 1
    totals = {u: 0 for u in users}
    for p in spec["posts"]:
        if p["author"] in totals:
            totals[p["author"]] += per_post.get(p["id"], 0)
    ranked = sorted(users, key=lambda u: (-totals[u], u))
    return ",".join(u + "=" + str(totals[u]) for u in ranked)
```

